/* C caller for the G1 sample calc: reads "i0 i1" lines, prints "i0 i1 status result" per line. */
#include <inttypes.h>
#include <stdio.h>

#include "omega_native.h" /* generated by tools/native, nothing typed by hand */

int main(void)
{
    uint64_t a, b;
    while (scanf("%" SCNu64 " %" SCNu64, &a, &b) == 2) {
        uint64_t r = 0;
        uint32_t s = omega_calc(&r, a, b);
        printf("%" PRIu64 " %" PRIu64 " %" PRIu32 " %" PRIu64 "\n", a, b, s, r);
    }
    return 0;
}
